// Localized deformation of a backlit macro texture, not seven flat radial masks.
(() => {
  const fields=[...document.querySelectorAll('.petal-field')];if(!fields.length)return;
  const viewport=()=>document.documentElement.style.setProperty('--visual-viewport',document.documentElement.clientWidth+'px');viewport();addEventListener('resize',viewport);
  const reduced=matchMedia('(prefers-reduced-motion: reduce)'),image=new Image();
  image.src='data:image/webp;base64,';
  const vertex='attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';
  const fragment=`precision highp float;
uniform vec2 resolution;uniform sampler2D petals;uniform float time;
float noise(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void main(){
 vec2 uv=gl_FragCoord.xy/resolution;
 float aspect=resolution.x/resolution.y;
 vec2 cover=aspect>1.5?vec2(1.,1.5/aspect):vec2(aspect/1.5,1.);
 vec2 q=(uv-.5)*cover+.5;
 float phase=6.2831853*time/6.8;
 vec2 near=(q-vec2(.43,.15))*vec2(1.6,2.1),left=(q-vec2(.05,.65))*vec2(2.1,1.6),right=(q-vec2(.9,.12))*vec2(2.8,2.3);
 q+=vec2(.012*sin(phase+q.y*2.3),.008*cos(phase+q.x*3.1))*exp(-dot(near,near));
 q+=vec2(-.010*sin(phase+.9),.006*cos(phase+1.8))*exp(-dot(left,left));
 q+=vec2(.014*sin(phase+2.3),-.009*cos(phase+2.9))*exp(-dot(right,right));
 vec2 blur=vec2(.0022);
 vec3 col=texture2D(petals,q).rgb*.28;
 col+=(texture2D(petals,q+vec2(blur.x,0.)).rgb+texture2D(petals,q-vec2(blur.x,0.)).rgb)*.16;
 col+=(texture2D(petals,q+vec2(0.,blur.y)).rgb+texture2D(petals,q-vec2(0.,blur.y)).rgb)*.12;
 col+=(texture2D(petals,q+blur).rgb+texture2D(petals,q-blur).rgb)*.08;
 col=mix(col,vec3(.945,.937,.902),.12);
 float luminance=dot(col,vec3(.2126,.7152,.0722));
 vec3 tint=vec3(.91,1.04,.81);tint/=dot(tint,vec3(.2126,.7152,.0722));
 col=mix(vec3(luminance),luminance*tint,.66);
 vec3 highlight=vec3(1.,1.,.965);highlight/=dot(highlight,vec3(.2126,.7152,.0722));
 col=mix(col,luminance*highlight,smoothstep(.83,1.,luminance));
 col+=(noise(gl_FragCoord.xy)-.5)*.024;
 gl_FragColor=vec4(col,1.);
}`;
  fields.forEach(field=>{
    const canvas=document.createElement('canvas');canvas.setAttribute('aria-hidden','true');
    const gl=canvas.getContext('webgl',{alpha:false,antialias:false,powerPreference:'low-power'});if(!gl)return;
    function compile(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(s));return s;}
    let program;try{program=gl.createProgram();gl.attachShader(program,compile(gl.VERTEX_SHADER,vertex));gl.attachShader(program,compile(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(program));}catch(e){console.warn('[petals]',e.message);return;}
    gl.useProgram(program);gl.bindBuffer(gl.ARRAY_BUFFER,gl.createBuffer());gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
    const loc=gl.getAttribLocation(program,'p');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
    const uRes=gl.getUniformLocation(program,'resolution'),uTime=gl.getUniformLocation(program,'time');
    gl.bindTexture(gl.TEXTURE_2D,gl.createTexture());gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    let visible=false,ready=false,raf=0,origin=0,last=0;
    const size=()=>{const b=field.getBoundingClientRect(),d=Math.min(1.25,devicePixelRatio||1);canvas.width=Math.max(1,Math.round(b.width*d));canvas.height=Math.max(1,Math.round(b.height*d));gl.viewport(0,0,canvas.width,canvas.height);gl.uniform2f(uRes,canvas.width,canvas.height);};
    const draw=t=>{if(!ready)return;gl.uniform1f(uTime,t);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);field.dataset.motionTime=t.toFixed(2);};
    function tick(now){if(!visible||document.hidden||reduced.matches){raf=0;return;}if(!origin)origin=now;if(now-last>31){draw((now-origin)/1000);last=now;}raf=requestAnimationFrame(tick);}
    const run=()=>{if(!ready)return;if(reduced.matches){draw(0);return;}if(visible&&!document.hidden&&!raf)raf=requestAnimationFrame(tick);};
    const load=()=>{if(ready)return;gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGB,gl.RGB,gl.UNSIGNED_BYTE,image);ready=true;field.append(canvas);size();draw(0);field.classList.add('is-live');run();};
    if(image.complete&&image.naturalWidth)load();else image.addEventListener('load',load,{once:true});
    new ResizeObserver(()=>{size();draw(0);run();}).observe(field);
    document.addEventListener('visibilitychange',run);reduced.addEventListener('change',run);
    if('IntersectionObserver'in window)new IntersectionObserver(e=>{visible=e[0].isIntersecting;run();},{threshold:.01}).observe(field);else{visible=true;run();}
  });
})();
